def print_segments(line_idx):
    line = lines[line_idx]
    segments = []
    in_segment = False
    start = 0
    for i, c in enumerate(line):
        if c != ' ' and c != '\n':
            if not in_segment:
                start = i
                in_segment = True
        else:
            if in_segment:
                segments.append((start, i, line[start:i]))
                in_segment = False
    if in_segment:
        segments.append((start, len(line), line[start:]))

    print(f"=== Line {line_idx+1} ===")
    for s, e, text in segments:
        # if text is long, truncate for display
        disp_text = text if len(text) < 60 else text[:25] + "..." + text[-25:]
        print(f"Col {s:4d} - {e:4d}: '{disp_text}'")

print_segments(50)
print_segments(51)
print_segments(52)

import re

# Read genealogy tree
with open('/app/dataset/genealogy_trees.txt', 'r') as f:
    lines = [line.rstrip('\r\n') for line in f]

# Find all characters that are letters (including Polish characters)
letter_pattern = re.compile(r'[a-zA-ZąćęłńóśźżĄĘĆŁŃÓŚŹŻ]')

letters_coords = []
for r, line in enumerate(lines):
    for c, char in enumerate(line):
        if letter_pattern.match(char):
            letters_coords.append((r, c, char))

# Group letters into horizontal words
words = []
if letters_coords:
    letters_coords.sort(key=lambda x: (x[0], x[1]))
    current_word = []
    for r, c, char in letters_coords:
        if not current_word:
            current_word = [(r, c, char)]
        else:
            prev_r, prev_c, _ = current_word[-1]
            if r == prev_r and c == prev_c + 1:
                current_word.append((r, c, char))
            else:
                words.append({
                    'r': current_word[0][0],
                    'c_start': current_word[0][1],
                    'c_end': current_word[-1][1],
                    'text': "".join(x[2] for x in current_word)
                })
                current_word = [(r, c, char)]
    if current_word:
        words.append({
            'r': current_word[0][0],
            'c_start': current_word[0][1],
            'c_end': current_word[-1][1],
            'text': "".join(x[2] for x in current_word)
        })

# Group words into person boxes
groups = []
visited_words = set()
for i, w1 in enumerate(words):
    if i in visited_words:
        continue
    group = [w1]
    visited_words.add(i)
    added = True
    while added:
        added = False
        for j, w2 in enumerate(words):
            if j in visited_words:
                continue
            is_close = False
            for wg in group:
                dr = abs(w2['r'] - wg['r'])
                max_start = max(w2['c_start'], wg['c_start'])
                min_end = min(w2['c_end'], wg['c_end'])
                horiz_dist = max_start - min_end
                if dr <= 2 and horiz_dist <= 15:
                    is_close = True
                    break
            if is_close:
                group.append(w2)
                visited_words.add(j)
                added = True
    groups.append(group)

boxes = []
for idx, group in enumerate(groups):
    group.sort(key=lambda x: (x['r'], x['c_start']))
    r_min = min(x['r'] for x in group)
    r_max = max(x['r'] for x in group)
    c_min = min(x['c_start'] for x in group)
    c_max = max(x['c_end'] for x in group)

    rows_dict = {}
    for x in group:
        rows_dict.setdefault(x['r'], []).append(x['text'])
    row_texts = [" ".join(rows_dict[r]) for r in sorted(rows_dict.keys())]
    full_text = " ".join(row_texts)

    # Filter out common non-names
    if full_text in ["FAMILY TREE GENERATOR", "FAMILY"]:
        continue
    if len(full_text) <= 1: # like 'x'
        continue

    boxes.append({
        'id': idx,
        'r_min': r_min,
        'r_max': r_max,
        'c_min': c_min,
        'c_max': c_max,
        'text': full_text
    })

