    # Let's search row r_min - 1 and r_min - 2 for drawing characters in the column span.
    start_pixels = []
    r_search = child_box['r_min'] - 1
    for r in [r_search, r_search - 1, r_search - 2]:
        if r < 0 or r >= len(lines):
            continue
        for c in range(child_box['c_min'] - 2, child_box['c_max'] + 3):
            if c < 0 or c >= len(lines[r]):
                continue
            char = lines[r][c]
            if char in drawing_chars:
                start_pixels.append((r, c))

    if not start_pixels:
        return None

    # Run BFS on drawing characters, only moving UP, LEFT, RIGHT, or DIAGONAL UP
    visited = set(start_pixels)
    queue = list(start_pixels)
    head = 0

    while head < len(queue):
        curr_r, curr_c = queue[head]
        head += 1

        # Check if we hit a box!
        # If the cell contains a letter, let's find if it's inside a box
        # Actually, let's check neighbors first. If a neighbor contains a letter,
        # we check which box it is.
        # Let's look around curr_r, curr_c
        for dr, dc in [(-1, 0), (0, -1), (0, 1), (-1, -1), (-1, 1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if nr < 0 or nr >= len(lines) or nc < 0 or nc >= len(lines[nr]):
                continue
