import re

with open('/app/dataset/genealogy_trees.txt', 'r') as f:
    lines = [line.rstrip('\r\n') for line in f]

letter_pattern = re.compile(r'[a-zA-ZąćęłńóśźżĄĘĆŁŃÓŚŹŻ]')
drawing_chars = set("+-/\\_|~│")
vertical_chars = set("|│")
horizontal_chars = set("-+~_=")

# Step 1: Find all basic words
words = []
for r, line in enumerate(lines):
    for match in re.finditer(r'[a-zA-ZąćęłńóśźżĄĘĆŁŃÓŚŹŻ]+', line):
        words.append({
            'r': r,
            'start': match.start(),
            'end': match.end() - 1,
            'text': match.group()
        })

# Step 2: Trace box from a word
def trace_box_from_word(word):
    r = word['r']
    start = word['start']
    end = word['end']

    L = None
    for c in range(start - 1, -1, -1):
        if c < len(lines[r]) and lines[r][c] in vertical_chars:
            L = c
            break

    R = None
    if r < len(lines):
        for c in range(end + 1, len(lines[r])):
            if lines[r][c] in vertical_chars:
                R = c
                break

    if L is None or R is None:
        return None

    T = None
    for row in range(r - 1, -1, -1):
        if L >= len(lines[row]) or R >= len(lines[row]):
            break
        segment = lines[row][L:R+1]
        horiz_count = sum(1 for c in segment if c in horizontal_chars)
        if horiz_count >= (R - L + 1) * 0.5:
            T = row
            break
        if lines[row][L] not in vertical_chars and lines[row][R] not in vertical_chars:
            if lines[row][L] not in drawing_chars or lines[row][R] not in drawing_chars:
                break

    B = None
    for row in range(r + 1, len(lines)):
        if L >= len(lines[row]) or R >= len(lines[row]):
            break
        segment = lines[row][L:R+1]
        horiz_count = sum(1 for c in segment if c in horizontal_chars)
        if horiz_count >= (R - L + 1) * 0.5:
            B = row
            break
        if lines[row][L] not in vertical_chars and lines[row][R] not in vertical_chars:
            if lines[row][L] not in drawing_chars or lines[row][R] not in drawing_chars:
                break

    if T is None or B is None:
        return None

    name_parts = []
    for row in range(T + 1, B):
        segment = lines[row][L+1:R]
        text_inside = segment.strip()
        text_inside = re.sub(r'[│|]', '', text_inside).strip()
        if text_inside:
            name_parts.append(text_inside)

    full_name = " ".join(name_parts)
    full_name = " ".join(full_name.split())

    return {
        'T': T,
        'B': B,
        'L': L,
        'R': R,
        'text': full_name
    }

boxes = []
seen_borders = set()
for word in words:
    box = trace_box_from_word(word)
    if box:
        border_key = (box['T'], box['B'], box['L'], box['R'])
        if border_key not in seen_borders:
            seen_borders.add(border_key)
            boxes.append(box)

# Assign IDs to boxes
for idx, box in enumerate(boxes):
    box['id'] = idx

print(f"Extracted {len(boxes)} clean perfect boxes.")

# Helper to find which box contains a coordinate (r, c)
def find_box_at(r, c):
    for box in boxes:
        if box['T'] <= r <= box['B'] and box['L'] <= c <= box['R']:
            return box
    return None

# Step 3: Find parent for each box
# To be robust, let's start BFS from top border row (T) of box
def find_parent_box(child_box):
    # Find any drawing characters above the top border T
    start_pixels = []
    T = child_box['T']
    # Look at row T-1 and T-2 in the col range child_box['L'] to child_box['R']
    for r in [T-1, T-2]:
        if r < 0 or r >= len(lines):
            continue
        for c in range(child_box['L'], child_box['R'] + 1):
            if c >= len(lines[r]):
                continue
            if lines[r][c] in drawing_chars:
                start_pixels.append((r, c))

    if not start_pixels:
        return None

    visited = set(start_pixels)
    queue = list(start_pixels)
    head = 0

    while head < len(queue):
        curr_r, curr_c = queue[head]
        head += 1

        # Check if we hit a box letters
        # We check the 8-neighbors of current pixel
        for dr, dc in [(-1, 0), (0, -1), (0, 1), (-1, -1), (-1, 1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if nr < 0 or nr >= len(lines) or nc < 0 or nc >= len(lines[nr]):
                continue

            # Check if neighbor is inside a box (that is NOT the child box itself)
            parent = find_box_at(nr, nc)
            if parent and parent['id'] != child_box['id']:
                return parent

            char = lines[nr][nc]
            # If neighbor is a drawing character, we traverse
            if char in drawing_chars:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return None

# Build parent links
parent_map = {} # child_id -> parent_id
for box in boxes:
    parent = find_parent_box(box)
    if parent:
        parent_map[box['id']] = parent['id']

print(f"Built parent map with {len(parent_map)} parent-child relationships.")

# Reconstruct lineage for Dawid Majtyka
def get_box_by_name(name):
    for box in boxes:
        if name.lower() in box['text'].lower():
            return box
    return None

dawid = get_box_by_name("Dawid Majtyka")
if dawid:
    print("\nTracing Dawid Majtyka:")
    curr = dawid
    generation = 0
    path = [curr]
    while curr['id'] in parent_map:
        curr = boxes[parent_map[curr['id']]]
        generation += 1
        print(f"G{generation}: {curr['text']} (Box {curr['id']}, T={curr['T']}, L={curr['L']})")
        path.append(curr)
else:
    print("Dawid Majtyka box not found!")

# Find great-great-grandparent (G4)
g4 = None
if len(path) >= 5:
    g4 = path[4]
    print(f"\nGreat-great-grandparent identified as: {g4['text']}")

if g4:
    # Build parent -> children map
    children_map = {} # parent_id -> list of child_ids
    for child_id, parent_id in parent_map.items():
        children_map.setdefault(parent_id, []).append(child_id)

    print(f"\nChildren of {g4['text']}:")
    g3_children = children_map.get(g4['id'], [])
    for child_id in g3_children:
        child_box = boxes[child_id]
        print(f"- {child_box['text']} (Box {child_box['id']})")

