                if word_matches_at(line1, last, pos_last):
                    for pos_first in range(max(0, pos_last - 15), min(len(line2), pos_last + 15)):
                        if line2[pos_first : pos_first + len(first)] == first:
                            if word_matches_at(line2, first, pos_first):
                                matched_people.append({
                                    'person': person,
                                    'type': 'split_line_2_1',
                                    'r1': r, 'r2': r+1,
                                    'c1_start': min(pos_first, pos_last),
                                    'c2_end': max(pos_first + len(first), pos_last + len(last))
                                })
                                found = True
                                break
                if found:
                    break
                start_idx = pos_last + 1

